builtin_set_layer:
POP P0
POP P1
MOV VL, P1
PUSH P0
RET
builtin_set_pos:
POP P0
POP P1
POP P2
MOV VX, P1
MOV VY, P2
PUSH P0
RET
builtin_screen_fill:
POP P0
POP P1
SFILL P1
PUSH P0
RET
builtin_screen_rotate:
; Args: direction, amount
POP P0
POP P1
POP P2
SROT P1, P2
PUSH P0
RET
builtin_screen_shift:
; Args: axis, amount
POP P0
POP P1
POP P2
SSHFT P1, P2
PUSH P0
RET
builtin_draw_char:
; Args: char (uses VX/VY position, VC color)
POP P0
POP P1
CHAR P1
PUSH P0
RET
builtin_write_text:
POP P0
POP P1
POP P2
MOV VC, P2
TEXT P1
PUSH P0
RET
builtin_key_available:
KEYSTAT P0
RET
builtin_key_read:
KEYIN P0
RET
builtin_key_clear:
KEYCLEAR
RET
builtin_random_range:
; Save return address in P3 (not P0, since RNDR will write its result to P0).
; Stack: [ret_addr, color_max, color_min] (top = last pushed = color_min)
; builtins with P0 as destination use P3 for the return address (see
; builtin_set_pointers for the same pattern).
POP P3
POP P1
POP P2
RNDR P0, P1, P2
PUSH P3
RET
builtin_strcat:
POP P3
POP P1
POP P2
STRCAT P1, P2
MOV P0, P1
PUSH P3
RET
